/// Whether the submitted trio equals the live successor's immutable snapshot
/// (the successor was created FROM a submitted trio — equality means a true
/// no-op). r2 W7.
fn trio_matches_row(
  row: sql.ListReferenceCallsForApplicationRow,
  trio: Trio,
) -> Bool {
  trio.name == row.contact_name
  && trio.email == effective_value(row.corrected_email, row.contact_email)
  && trio.phone == effective_value(row.corrected_phone, row.contact_phone)
}
